-- GenChem Ch12 (Electrochemistry) — Batch 1 of 4: Cell types, electron flow, electrode charge designations & cell diagrams
-- 23 questions, all confidence >=4 (independently re-verified vs OpenStax Chemistry: Atoms First 2e, Ch.16; every cell-potential, sign convention, Faraday/electron count, Nernst term, and ΔG/Keq value re-computed).
-- Cross-batch + cross-chapter deduped (vs Ch11 Redox, Ch10 Acids & Bases, Ch4 Compounds); final dedup audit PASS (0 genuine conflicts; internal + systematic recall-answer-leak sweep + cross-chapter).
-- AAMC foundations in this batch: 4C Electrochemistry (GC) (per-row foundation/content_category/discipline below). Answer key balanced A/B/C/D = 24/24/24/24 across the full 96-question chapter.
-- Re-runnable: subtopic-scoped DELETE. Run the four batches in any order in the Supabase SQL editor.
BEGIN;
DELETE FROM questions WHERE topic = 'Electrochemistry' AND subtopic IN ('Cell Types & Electron Flow', 'Electrode Charge Designations', 'Cell Diagram Notation');

-- Q1 [Cell Types & Electron Flow · easy · Skill 1 · 4C Electrochemistry (GC) · ans A] (g1)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Electrochemistry', 'Cell Types & Electron Flow',
    $qt1$A galvanic (voltaic) cell is built from a nickel electrode immersed in \(\text{Ni}^{2+}(aq)\) and a silver electrode immersed in \(\text{Ag}^{+}(aq)\), with the two half-cells joined by a salt bridge. Because nickel is the more easily oxidized of the two metals, it serves as the anode and silver serves as the cathode. As the cell operates spontaneously, one electrode steadily loses mass while the other steadily gains mass. Which electrode loses mass and which gains mass, and why?$qt1$,
    $op1$[{"label":"A","text":"The nickel (anode) electrode loses mass because its metal atoms are oxidized to \\(\\text{Ni}^{2+}\\) ions that dissolve into solution, while the silver (cathode) electrode gains mass because \\(\\text{Ag}^{+}\\) ions are reduced and deposit as solid metal on it."},{"label":"B","text":"The nickel (anode) electrode gains mass because \\(\\text{Ni}^{2+}\\) ions plate onto it, while the silver (cathode) electrode loses mass because its metal is oxidized and dissolves into solution."},{"label":"C","text":"Both electrodes lose mass, because metal atoms are oxidized and dissolve into solution at the anode and at the cathode simultaneously."},{"label":"D","text":"Neither electrode changes mass, because the cell is balanced: every electron released at one electrode is taken up at the other, so no net metal is transferred."}]$op1$::jsonb,
    'A',
    $ex1$This is a General Chemistry question that falls under the content category 'Electrochemistry (GC)'. The answer to this question is A because in a galvanic cell oxidation occurs at the anode and reduction occurs at the cathode. Nickel is the more easily oxidized metal, so the nickel electrode is the anode: its atoms give up electrons and leave the solid as \(\text{Ni}^{2+}\) ions that enter the solution (\(\text{Ni}(s) \rightarrow \text{Ni}^{2+}(aq) + 2e^-\)), so that electrode steadily loses mass. The electrons travel through the external wire to the silver electrode, the cathode, where dissolved \(\text{Ag}^{+}\) ions are reduced and deposit as solid silver (\(\text{Ag}^{+}(aq) + e^- \rightarrow \text{Ag}(s)\)), so that electrode steadily gains mass. Thus the anode (nickel) loses mass and the cathode (silver) gains mass. (Choice B) This reverses the two electrodes: it is the anode metal, not the cathode metal, that is oxidized and dissolves, and it is the cathode, not the anode, on which cations plate out and add mass; the nickel anode loses mass and the silver cathode gains it, the opposite of what this choice states. (Choice C) Only the anode metal is oxidized and dissolves; at the cathode metal is deposited rather than dissolved, so the cathode gains mass instead of losing it, and the two electrodes cannot both lose mass. (Choice D) Although charge is conserved (electrons lost at the anode equal those gained at the cathode), the metal is physically transferred: \(\text{Ni}\) atoms leave the anode as ions and \(\text{Ag}\) atoms build up on the cathode, so the electrode masses do change measurably even though the electron count is balanced. Skill 1$ex1$,
    'easy', '4C', $cc1$Electrochemistry (GC)$cc1$, 'general-chemistry', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'reversed_relationship', $a1B$Swaps which electrode is oxidized vs. reduced, claiming the cathode dissolves and the anode plates (anode/cathode mass-change reversal)$a1B$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a1C$Believes metal dissolves at both electrodes, failing to recognize that the cathode is a deposition (reduction) site, not a dissolution site$a1C$ FROM q
UNION ALL SELECT id, 'D', 'partial_truth', $a1D$Correctly notes electron/charge balance but wrongly concludes no net mass change, conflating conservation of charge with no transfer of metal$a1D$ FROM q;

-- Q2 [Cell Types & Electron Flow · easy · Skill 1 · 4C Electrochemistry (GC) · ans B] (g2)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Electrochemistry', 'Cell Types & Electron Flow',
    $qt2$A galvanic (voltaic) cell is built from a magnesium electrode dipped in \(\text{Mg}^{2+}\) solution and a silver electrode dipped in \(\text{Ag}^+\) solution, connected by an external wire and a salt bridge. In this spontaneous cell, magnesium is oxidized and silver ion is reduced. Through the external wire connecting the two electrodes, in which direction do the electrons travel?$qt2$,
    $op2$[{"label":"A","text":"From the silver electrode to the magnesium electrode (cathode to anode)"},{"label":"B","text":"From the magnesium electrode to the silver electrode (anode to cathode)"},{"label":"C","text":"From the magnesium electrode to the silver electrode (cathode to anode)"},{"label":"D","text":"Electrons do not travel through the wire; they migrate through the salt bridge instead"}]$op2$::jsonb,
    'B',
    $ex2$This is a General Chemistry question that falls under the content category 'Electrochemistry (GC)'. The answer to this question is B because in any galvanic cell, oxidation occurs at the anode and reduction occurs at the cathode. Here magnesium is oxidized (\(\text{Mg} \rightarrow \text{Mg}^{2+} + 2e^-\)), so the magnesium electrode is the anode, and silver ion is reduced (\(\text{Ag}^+ + e^- \rightarrow \text{Ag}\)), so the silver electrode is the cathode. The oxidation half-reaction releases electrons at the anode, and those electrons travel through the external wire to the cathode, where they are consumed by reduction. Therefore electrons flow from the magnesium (anode) to the silver (cathode), i.e., anode to cathode through the wire. (Choice A) This reverses the actual direction: it describes cathode-to-anode flow, which would correspond to where conventional current flows, not where the negatively charged electrons physically travel; electrons always move away from the anode where oxidation generates them, toward the cathode. (Choice C) This states the correct physical endpoints (magnesium to silver) but mislabels them as "cathode to anode"; magnesium is the anode and silver is the cathode, so the parenthetical direction contradicts the named electrodes. (Choice D) This misidentifies the role of the salt bridge: electrons travel through the metal wire, while the salt bridge carries ions (not electrons) to maintain charge balance, so it is incorrect to claim the wire carries no electrons. Skill 1$ex2$,
    'easy', '4C', $cc2$Electrochemistry (GC)$cc2$, 'general-chemistry', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'reversed_relationship', $a2A$Confuses electron-flow direction with conventional-current direction (cathode to anode)$a2A$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a2C$Correct physical path but swaps the anode/cathode labels for the two electrodes$a2C$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a2D$Believes the salt bridge, not the external wire, conducts the electrons$a2D$ FROM q;

-- Q3 [Cell Types & Electron Flow · easy · Skill 1 · 4C Electrochemistry (GC) · ans C] (g3)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Electrochemistry', 'Cell Types & Electron Flow',
    $qt3$In a Downs-type apparatus, a battery is connected to two inert electrodes immersed in molten (liquid) sodium chloride. As long as the battery drives current through the cell, sodium metal collects at one electrode and chlorine gas bubbles off at the other; when the battery is disconnected, the process stops entirely. Which classification of the cell, paired with the correct thermodynamic description of the \(\text{NaCl}(l) \rightarrow \text{Na}(l) + \tfrac{1}{2}\text{Cl}_2(g)\) reaction it drives, is correct?$qt3$,
    $op3$[{"label":"A","text":"Galvanic (voltaic) cell; the reaction it drives is non-spontaneous (\\(\\Delta G > 0\\), \\(E_{\\text{cell}} < 0\\))"},{"label":"B","text":"Electrolytic cell; the reaction it drives is spontaneous (\\(\\Delta G < 0\\), \\(E_{\\text{cell}} > 0\\))"},{"label":"C","text":"Electrolytic cell; the reaction it drives is non-spontaneous (\\(\\Delta G > 0\\), \\(E_{\\text{cell}} < 0\\))"},{"label":"D","text":"Galvanic (voltaic) cell; the reaction it drives is spontaneous (\\(\\Delta G < 0\\), \\(E_{\\text{cell}} > 0\\))"}]$op3$::jsonb,
    'C',
    $ex3$This is a General Chemistry question that falls under the content category 'Electrochemistry (GC)'. The answer to this question is C because the cell only operates while an external power source (the battery) supplies energy, and it stops the instant that source is removed; this is the defining behavior of an electrolytic cell. An electrolytic cell uses electrical energy to force a reaction that does not occur on its own, so the decomposition \(\text{NaCl}(l) \rightarrow \text{Na}(l) + \tfrac{1}{2}\text{Cl}_2(g)\) it drives is non-spontaneous, with \(\Delta G > 0\) and \(E_{\text{cell}} < 0\). (The battery does electrical work to overcome this, which is exactly why disconnecting it halts the process.) (Choice A) This choice correctly recognizes the reaction as non-spontaneous but mislabels the cell as galvanic; a galvanic cell generates its own current from a spontaneous reaction and needs no battery, the opposite of what is described. (Choice B) This choice correctly identifies the electrolytic cell but then mislabels the forced reaction as spontaneous; a reaction that requires continuous external power to proceed cannot be spontaneous, so \(\Delta G\) and \(E_{\text{cell}}\) must have the non-spontaneous signs. (Choice D) This choice inverts both features: it treats the device as a self-powered galvanic cell running a spontaneous reaction, whereas the cell consumes external electrical energy to drive a non-spontaneous reaction. Skill 1$ex3$,
    'easy', '4C', $cc3$Electrochemistry (GC)$cc3$, 'general-chemistry', 1, 75
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'process_step_confusion', $a3A$Right spontaneity, wrong cell type (galvanic vs electrolytic)$a3A$ FROM q
UNION ALL SELECT id, 'B', 'partial_truth', $a3B$Right cell type, wrong spontaneity sign$a3B$ FROM q
UNION ALL SELECT id, 'D', 'reversed_relationship', $a3D$Inverts both cell type and spontaneity (treats forced cell as self-powered)$a3D$ FROM q;

-- Q4 [Cell Types & Electron Flow · medium · Skill 2 · 4C Electrochemistry (GC) · ans D] (g4)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Electrochemistry', 'Cell Types & Electron Flow',
    $qt4$A galvanic cell is constructed and operated according to the cell notation \(\text{Fe}\,|\,\text{Fe}^{2+}\,||\,\text{Sn}^{2+}\,|\,\text{Sn}\), where the iron half-cell is the anode and the tin half-cell is the cathode. While the cell delivers current to an external resistor connected by a metal wire, which statement correctly describes the relationship between the conventional current and the electron flow in that wire?$qt4$,
    $op4$[{"label":"A","text":"Electrons travel through the wire from the Fe electrode to the Sn electrode, while the conventional current is directed from the Sn electrode to the Fe electrode; the conventional current is larger in magnitude."},{"label":"B","text":"Electrons travel through the wire from the Sn electrode to the Fe electrode, while the conventional current is directed from the Fe electrode to the Sn electrode; the two have equal magnitude."},{"label":"C","text":"Electrons and conventional current both travel through the wire from the Fe electrode to the Sn electrode, in the same direction and with equal magnitude."},{"label":"D","text":"Electrons travel through the wire from the Fe electrode to the Sn electrode, while the conventional current is directed from the Sn electrode to the Fe electrode; the two have equal magnitude."}]$op4$::jsonb,
    'D',
    $ex4$This is a General Chemistry question that falls under the content category 'Electrochemistry (GC)'. The answer to this question is D because in a galvanic cell oxidation occurs at the anode and reduction occurs at the cathode, so electrons are released at the iron anode \((\text{Fe} \rightarrow \text{Fe}^{2+} + 2e^-)\) and consumed at the tin cathode \((\text{Sn}^{2+} + 2e^- \rightarrow \text{Sn})\). Electrons therefore move through the external wire from the anode to the cathode, i.e., from the Fe electrode to the Sn electrode. Conventional current is defined as the direction of flow of positive charge, which is exactly opposite to the direction of electron flow; it is therefore directed from the Sn electrode (cathode) to the Fe electrode (anode) through the wire. Because conventional current is simply the same charge transport described with the opposite sign convention (a flow of \(+\) charge one way is identical to a flow of \(-\) charge the other way), the two have equal magnitude. (Choice A) This correctly identifies the opposite directions but incorrectly claims the conventional current is larger; the same charge transport viewed under two sign conventions has identical magnitude, so neither is larger. (Choice B) This reverses both directions: it places electron flow from Sn to Fe and conventional current from Fe to Sn, which would require oxidation at the tin cathode and reduction at the iron anode, contradicting the assigned roles of the electrodes. (Choice C) This treats electrons and conventional current as flowing in the same direction; by definition conventional current is the direction of positive-charge flow and is opposite to electron flow, so they cannot point the same way. Skill 2$ex4$,
    'medium', '4C', $cc4$Electrochemistry (GC)$cc4$, 'general-chemistry', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'partial_truth', $a4A$correct opposite directions but falsely claims unequal magnitudes$a4A$ FROM q
UNION ALL SELECT id, 'B', 'reversed_relationship', $a4B$swaps anode and cathode, reversing both electron and current directions$a4B$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a4C$believes conventional current and electron flow point the same way$a4C$ FROM q;

-- Q5 [Cell Types & Electron Flow · medium · Skill 2 · 4C Electrochemistry (GC) · ans A] (g5)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Electrochemistry', 'Cell Types & Electron Flow',
    $qt5$A galvanic cell is constructed from two identical copper electrodes. One electrode is immersed in a \(0.10\ \text{M}\ \text{Cu}^{2+}\) solution and the other in a \(1.0\ \text{M}\ \text{Cu}^{2+}\) solution, with the two half-cells joined by a salt bridge. Because the electrodes and the electrode material are the same, the standard potential of each half-reaction \(\left(\text{Cu}^{2+} + 2e^- \rightarrow \text{Cu},\ E^{\circ} = +0.34\ \text{V}\right)\) is identical, so \(E^{\circ}_{\text{cell}} = 0\ \text{V}\); the cell nonetheless generates a measurable voltage and runs spontaneously. Which half-cell serves as the cathode, and why?$qt5$,
    $op5$[{"label":"A","text":"The \\(1.0\\ \\text{M}\\) half-cell, because reduction of \\(\\text{Cu}^{2+}\\) to \\(\\text{Cu}\\) occurs there as the cell moves toward equalizing the two concentrations."},{"label":"B","text":"The \\(0.10\\ \\text{M}\\) half-cell, because oxidation of \\(\\text{Cu}\\) to \\(\\text{Cu}^{2+}\\) occurs there as the cell moves toward equalizing the two concentrations."},{"label":"C","text":"The \\(1.0\\ \\text{M}\\) half-cell, because oxidation of \\(\\text{Cu}\\) to \\(\\text{Cu}^{2+}\\) occurs there, raising its concentration further."},{"label":"D","text":"Neither half-cell is the cathode, because identical electrodes give \\(E^{\\circ}_{\\text{cell}} = 0\\ \\text{V}\\) and no net electron flow can occur."}]$op5$::jsonb,
    'A',
    $ex5$This is a General Chemistry question that falls under the content category 'Electrochemistry (GC)'. The answer to this question is A because a concentration cell is a special galvanic cell in which both half-cells contain the same electrode and the same redox couple, so the two standard reduction potentials cancel and \(E^{\circ}_{\text{cell}} = +0.34 - 0.34 = 0\ \text{V}\). The driving force is not a difference in \(E^{\circ}\) but the concentration gradient: the system spontaneously acts to equalize the two \(\text{Cu}^{2+}\) concentrations. To do this, \(\text{Cu}^{2+}\) must be consumed (reduced) in the more concentrated solution and produced (by oxidation of the Cu electrode) in the more dilute solution. Reduction defines the cathode, so the \(1.0\ \text{M}\) half-cell is the cathode and the \(0.10\ \text{M}\) half-cell is the anode. The Nernst equation confirms a spontaneous, positive cell voltage: \(E_{\text{cell}} = E^{\circ}_{\text{cell}} - \frac{0.0592}{n}\log Q\), with \(n = 2\) and \(Q = \frac{[\text{Cu}^{2+}]_{\text{dilute, anode}}}{[\text{Cu}^{2+}]_{\text{conc, cathode}}} = \frac{0.10}{1.0} = 0.10\), giving \(E_{\text{cell}} = 0 - \frac{0.0592}{2}\log(0.10) = -0.0296 \times (-1) = +0.0296\ \text{V} > 0\). The positive value verifies the spontaneous direction and that the concentrated side is indeed the cathode. (Choice B) This choice correctly identifies that the dilute side undergoes oxidation but mislabels it: oxidation occurs at the anode, not the cathode, so the \(0.10\ \text{M}\) half-cell is the anode rather than the cathode. (Choice C) This choice picks the correct side (the \(1.0\ \text{M}\) half-cell) but assigns the wrong process; oxidation would raise the concentrated side's \(\text{Cu}^{2+}\) and widen the gradient, the opposite of the spontaneous tendency, so the concentrated side must undergo reduction, not oxidation. (Choice D) This choice confuses a zero standard potential with a zero actual potential; although \(E^{\circ}_{\text{cell}} = 0\), the unequal concentrations make \(Q \neq 1\), so the Nernst equation yields a nonzero \(E_{\text{cell}}\) and current does flow until the concentrations equalize. Skill 2$ex5$,
    'medium', '4C', $cc5$Electrochemistry (GC)$cc5$, 'general-chemistry', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'reversed_relationship', $a5B$Correct process, wrong electrode label (calls the oxidation site the cathode)$a5B$ FROM q
UNION ALL SELECT id, 'C', 'process_step_confusion', $a5C$Right side but assigns oxidation instead of reduction, widening rather than closing the gradient$a5C$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a5D$Treats E°cell = 0 as Ecell = 0, ignoring the Nernst concentration term$a5D$ FROM q;

-- Q6 [Cell Types & Electron Flow · medium · Skill 2 · 4C Electrochemistry (GC) · ans B] (g6)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Electrochemistry', 'Cell Types & Electron Flow',
    $qt6$A galvanic cell is assembled and its standard cell potential is reported as \(E^{\circ}_{\text{cell}} = +0.78\ \text{V}\). Using the thermodynamic relationship \(\Delta G^{\circ} = -nFE^{\circ}_{\text{cell}}\), in which \(n\) is the number of moles of electrons transferred and \(F = 96{,}485\ \text{C/mol e}^-\), what is the sign of \(\Delta G^{\circ}\) for the cell reaction, and is the reaction as written spontaneous under standard conditions?$qt6$,
    $op6$[{"label":"A","text":"\\(\\Delta G^{\\circ} > 0\\), and the reaction is nonspontaneous as written."},{"label":"B","text":"\\(\\Delta G^{\\circ} < 0\\), and the reaction is spontaneous as written."},{"label":"C","text":"\\(\\Delta G^{\\circ} > 0\\), and the reaction is spontaneous as written."},{"label":"D","text":"\\(\\Delta G^{\\circ} < 0\\), and the reaction is nonspontaneous as written."}]$op6$::jsonb,
    'B',
    $ex6$This is a General Chemistry question that falls under the content category 'Electrochemistry (GC)'. The answer to this question is B because \(E^{\circ}_{\text{cell}}\) and \(\Delta G^{\circ}\) are tied together by \(\Delta G^{\circ} = -nFE^{\circ}_{\text{cell}}\), in which \(n\) and \(F = 96{,}485\ \text{C/mol e}^-\) are both positive quantities. The leading negative sign means the two quantities must always carry opposite signs: a positive \(E^{\circ}_{\text{cell}}\) forces a negative \(\Delta G^{\circ}\), and a negative \(E^{\circ}_{\text{cell}}\) forces a positive \(\Delta G^{\circ}\). Here \(E^{\circ}_{\text{cell}} = +0.78\ \text{V} > 0\), so \(\Delta G^{\circ} = -nF(+0.78\ \text{V}) < 0\). A negative \(\Delta G^{\circ}\) is the thermodynamic definition of a spontaneous process, so the reaction proceeds spontaneously as written. This is also exactly why a galvanic (voltaic) cell has \(E^{\circ}_{\text{cell}} > 0\): it converts the free energy of a spontaneous redox reaction into electrical work. (Choice A) This treats \(E^{\circ}_{\text{cell}}\) and \(\Delta G^{\circ}\) as carrying the same sign, concluding that a positive potential gives a positive \(\Delta G^{\circ}\) and a nonspontaneous reaction; this ignores the negative sign in \(\Delta G^{\circ} = -nFE^{\circ}_{\text{cell}}\), which guarantees the two have opposite signs. (Choice C) This correctly identifies the reaction as spontaneous but pairs it with the wrong sign of \(\Delta G^{\circ}\); a spontaneous process must have \(\Delta G^{\circ} < 0\), so reporting \(\Delta G^{\circ} > 0\) alongside spontaneity is internally contradictory and reflects flipping the sign relationship. (Choice D) This obtains the correct sign \(\Delta G^{\circ} < 0\) but then mislabels a negative-free-energy reaction as nonspontaneous; by definition \(\Delta G^{\circ} < 0\) corresponds to a spontaneous reaction, so the spontaneity conclusion is reversed. Skill 2$ex6$,
    'medium', '4C', $cc6$Electrochemistry (GC)$cc6$, 'general-chemistry', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a6A$Treats E_cell and dG as carrying the same sign, so a positive potential is read as positive dG and nonspontaneous$a6A$ FROM q
UNION ALL SELECT id, 'C', 'reversed_relationship', $a6C$Correctly calls the reaction spontaneous but pairs it with positive dG, flipping the dG-spontaneity sign rule$a6C$ FROM q
UNION ALL SELECT id, 'D', 'partial_truth', $a6D$Gets dG < 0 right but mislabels a negative-free-energy reaction as nonspontaneous$a6D$ FROM q;

-- Q7 [Cell Types & Electron Flow · medium · Skill 2 · 4C Electrochemistry (GC) · ans C] (g7)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Electrochemistry', 'Cell Types & Electron Flow',
    $qt7$A particular redox reaction, written in a specific direction, is found to have a positive standard free energy change, \(\Delta G^{\circ} > 0\), under standard conditions. A chemist wants to carry out this reaction in the exact direction as written using an electrochemical cell. Which of the following correctly classifies the cell that would accomplish this, gives the sign of its standard cell potential \(E^{\circ}_{\text{cell}}\), and states whether an external power source is required?$qt7$,
    $op7$[{"label":"A","text":"It is a galvanic cell with a positive \\(E^{\\circ}_{\\text{cell}}\\), and no external power source is needed because the reaction proceeds on its own."},{"label":"B","text":"It is an electrolytic cell with a positive \\(E^{\\circ}_{\\text{cell}}\\), and an external power source is needed to drive the reaction."},{"label":"C","text":"It is an electrolytic cell with a negative \\(E^{\\circ}_{\\text{cell}}\\), and an external power source is required to drive the reaction in the direction written."},{"label":"D","text":"It is a galvanic cell with a negative \\(E^{\\circ}_{\\text{cell}}\\), yet an external power source is still required to push the reaction forward."}]$op7$::jsonb,
    'C',
    $ex7$This is a General Chemistry question that falls under the content category 'Electrochemistry (GC)'. The answer to this question is C because the three facts must be combined consistently. The relationship \(\Delta G^{\circ} = -nFE^{\circ}_{\text{cell}}\) links free energy and cell potential, where \(n\) and \(F\) are both positive. Given that \(\Delta G^{\circ} > 0\), the product \(-nFE^{\circ}_{\text{cell}}\) must be positive, which forces \(E^{\circ}_{\text{cell}}\) to be negative. A reaction with \(\Delta G^{\circ} > 0\) is nonspontaneous in the direction written, so it cannot run on its own in a galvanic cell; instead, it must be forced by an external power source, which is the defining feature of an electrolytic cell. Thus the cell is electrolytic, \(E^{\circ}_{\text{cell}}\) is negative, and an external power source is required. (Choice A) This treats the reaction as spontaneous, assigning a galvanic cell, a positive \(E^{\circ}_{\text{cell}}\), and no power source; that contradicts the given \(\Delta G^{\circ} > 0\), which describes a nonspontaneous reaction. (Choice B) The classification as electrolytic and the need for a power source are correct, but the sign of \(E^{\circ}_{\text{cell}}\) is wrong: \(\Delta G^{\circ} = -nFE^{\circ}_{\text{cell}}\) requires a negative \(E^{\circ}_{\text{cell}}\) when \(\Delta G^{\circ} > 0\), not a positive one. (Choice D) This is internally inconsistent: by definition a galvanic cell operates spontaneously and needs no external source, so labeling the cell galvanic while also stating it must be externally driven combines two mutually exclusive descriptions. Skill 2$ex7$,
    'medium', '4C', $cc7$Electrochemistry (GC)$cc7$, 'general-chemistry', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'misconception', $a7A$treats a positive-dG reaction as spontaneous, assigning galvanic cell with positive E-cell and no power source$a7A$ FROM q
UNION ALL SELECT id, 'B', 'reversed_relationship', $a7B$correct electrolytic classification but inverts the sign of E-cell from the dG = -nFE relationship$a7B$ FROM q
UNION ALL SELECT id, 'D', 'partial_truth', $a7D$correct negative E-cell and power-source need but pairs them with a galvanic label, an internally inconsistent classification$a7D$ FROM q;

-- Q8 [Cell Types & Electron Flow · medium · Skill 2 · 4C Electrochemistry (GC) · ans D] (g8)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Electrochemistry', 'Cell Types & Electron Flow',
    $qt8$A jeweler electroplates a copper pendant with a thin layer of silver by making the pendant one electrode and a bar of pure silver the other electrode, both immersed in a \(\text{AgNO}_3\) solution and connected to an external power source. As the cell operates, silver metal deposits onto the copper pendant according to \(\text{Ag}^+ + e^- \rightarrow \text{Ag}(s)\), while the silver bar slowly dissolves. At which electrode does reduction occur, and how do electrons move through the external wire compared with a galvanic cell?$qt8$,
    $op8$[{"label":"A","text":"Reduction occurs at the silver bar, and electrons travel from the silver bar to the pendant through the wire — the same anode-to-cathode direction as in a galvanic cell, but driven rather than spontaneous."},{"label":"B","text":"Reduction occurs at the silver bar, and electrons travel from the pendant to the silver bar through the wire — the opposite direction from a galvanic cell because the process is non-spontaneous."},{"label":"C","text":"Reduction occurs at the copper pendant, and electrons travel from the pendant to the silver bar through the wire — the reverse of a galvanic cell because the power source drives current backward."},{"label":"D","text":"Reduction occurs at the copper pendant, and electrons travel from the silver bar to the pendant through the wire — the same anode-to-cathode direction as in a galvanic cell, but here driven by the power source rather than occurring spontaneously."}]$op8$::jsonb,
    'D',
    $ex8$This is a General Chemistry question that falls under the content category 'Electrochemistry (GC)'. The answer to this question is D because the electrode where reduction happens is by definition the cathode, and silver ion is being reduced and plated onto the copper pendant (\(\text{Ag}^+ + e^- \rightarrow \text{Ag}(s)\)), so the pendant is the cathode. The silver bar, where neutral silver is oxidized to \(\text{Ag}^+\) to replenish the solution (\(\text{Ag} \rightarrow \text{Ag}^+ + e^-\)), is the anode. In every electrochemical cell — galvanic or electrolytic — oxidation occurs at the anode and reduction at the cathode, and electrons in the external wire always travel from the anode to the cathode; here that means from the silver bar to the copper pendant. The defining contrast is the driving force, not the direction of electron travel: a galvanic cell pushes electrons from anode to cathode spontaneously (\(E_{\text{cell}} > 0\), \(\Delta G < 0\)), whereas this electrolytic cell is non-spontaneous and the external power source forces electrons in that same anode-to-cathode direction (\(E_{\text{cell}} < 0\), \(\Delta G > 0\)). (Choice A) keeps the correct anode-to-cathode electron direction and the driven-rather-than-spontaneous contrast, but it mislabels the dissolving silver bar as the site of reduction; the silver bar is being oxidized (\(\text{Ag} \rightarrow \text{Ag}^+ + e^-\)), so it is the anode, and reduction takes place at the pendant instead. (Choice B) places reduction at the silver bar, but the silver bar is being oxidized (it dissolves), so it is the anode, not the cathode; it also reverses the universal anode-to-cathode electron direction, mistakenly assuming non-spontaneity flips which way electrons move through the wire. (Choice C) correctly identifies the copper pendant as the site of reduction (the cathode) but then sends electrons from the pendant to the silver bar — that is cathode-to-anode, the reverse of the actual anode-to-cathode flow; electrons always arrive at the cathode, never leave it. Skill 2$ex8$,
    'medium', '4C', $cc8$Electrochemistry (GC)$cc8$, 'general-chemistry', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'partial_truth', $a8A$Keeps the correct anode-to-cathode electron direction and driven-vs-spontaneous contrast but mislabels the oxidizing silver bar as the reduction site.$a8A$ FROM q
UNION ALL SELECT id, 'B', 'misconception', $a8B$Assigns reduction to the dissolving (oxidizing) silver bar and assumes non-spontaneity reverses the universal anode-to-cathode electron direction.$a8B$ FROM q
