-- Q15 [Electrode Charge Designations · medium · Skill 2 · 4C Electrochemistry (GC) · ans D] (g16)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Electrochemistry', 'Electrode Charge Designations',
    $qt16$A student builds a galvanic cell using a magnesium electrode in \(\text{Mg}^{2+}\) solution and a nickel electrode in \(\text{Ni}^{2+}\) solution, connected by a wire and a salt bridge. With a voltmeter in place, the student observes that electrons flow out of the magnesium electrode and through the external wire. Considering the electrode at which these electrons arrive, what is that electrode's role in the cell and the sign of its charge?$qt16$,
    $op16$[{"label":"A","text":"It is the anode and carries a negative charge."},{"label":"B","text":"It is the cathode and carries a negative charge."},{"label":"C","text":"It is the anode and carries a positive charge."},{"label":"D","text":"It is the cathode and carries a positive charge."}]$op16$::jsonb,
    'D',
    $ex16$This is a General Chemistry question that falls under the content category 'Electrochemistry (GC)'. The answer to this question is D because in any electrochemical cell electrons travel through the external wire from the anode to the cathode. The problem states that electrons flow out of the magnesium electrode, so \(\text{Mg}\) is being oxidized (\(\text{Mg} \rightarrow \text{Mg}^{2+} + 2e^-\)) and is therefore the anode. The electrons then arrive at the nickel electrode, which is consequently the cathode, where reduction occurs (\(\text{Ni}^{2+} + 2e^- \rightarrow \text{Ni}\)). The charge sign is fixed by the cell type: this is a galvanic (spontaneous) cell, in which the anode is the negative terminal and the cathode is the positive terminal. The destination electrode is the cathode, so it carries a positive charge. (Choice A) This both mislabels the destination electrode as the anode and assigns it a negative charge by reasoning that the electrode "receiving" electrons must be negatively charged; in fact the cathode in a galvanic cell is positive, and the electrode receiving electrons is the cathode, not the anode. (Choice B) This correctly identifies the destination electrode as the cathode but assigns it a negative charge; that is the electrolytic-cell convention. In a galvanic cell the cathode is positive, so applying the electrolytic sign reverses the correct relationship. (Choice C) This mislabels the destination (nickel) electrode as the anode; the anode is the source of electrons (magnesium), not the electrode where electrons arrive, so the role is incorrect even though the positive sign coincidentally matches the galvanic cathode. Skill 2$ex16$,
    'medium', '4C', $cc16$Electrochemistry (GC)$cc16$, 'general-chemistry', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'process_step_confusion', $a16A$treats the electron-receiving electrode as a negative anode by assuming incoming electrons make it negative$a16A$ FROM q
UNION ALL SELECT id, 'B', 'reversed_relationship', $a16B$applies the electrolytic-cell sign convention (cathode = negative) to a galvanic cell$a16B$ FROM q
UNION ALL SELECT id, 'C', 'misconception', $a16C$labels the electron-receiving electrode as the anode while keeping the correct galvanic positive sign$a16C$ FROM q;

-- Q16 [Electrode Charge Designations · medium · Skill 2 · 4C Electrochemistry (GC) · ans B] (g18)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Electrochemistry', 'Electrode Charge Designations',
    $qt18$To extract magnesium, an industrial plant electrolyzes molten magnesium chloride, \(\text{MgCl}_2(l)\), using two inert electrodes connected to a direct-current power supply. The supply pumps electrons out of one electrode and into the other, forcing the non-spontaneous decomposition that liberates molten magnesium at one electrode and chlorine gas at the other. Free \(\text{Mg}^{2+}\) and \(\text{Cl}^{-}\) ions drift through the melt toward whichever electrode draws them. Considering how the power supply charges each electrode, which statement correctly pairs the charge sign of each electrode with the ion it attracts?$qt18$,
    $op18$[{"label":"A","text":"The anode is negative and attracts the \\(\\text{Cl}^{-}\\) anions, while the cathode is positive and attracts the \\(\\text{Mg}^{2+}\\) cations."},{"label":"B","text":"The anode is positive and attracts the \\(\\text{Cl}^{-}\\) anions, while the cathode is negative and attracts the \\(\\text{Mg}^{2+}\\) cations."},{"label":"C","text":"The anode is positive and attracts the \\(\\text{Mg}^{2+}\\) cations, while the cathode is negative and attracts the \\(\\text{Cl}^{-}\\) anions."},{"label":"D","text":"The anode is negative, where the \\(\\text{Mg}^{2+}\\) ions are reduced, while the cathode is positive, where the \\(\\text{Cl}^{-}\\) ions are oxidized."}]$op18$::jsonb,
    'B',
    $ex18$This is a General Chemistry question that falls under the content category 'Electrochemistry (GC)'. The answer to this question is B because in an electrolytic cell the power supply, not a spontaneous reaction, sets the electrode charges: it pulls electrons out of the anode and pushes them into the cathode. Because the anode is connected to the positive (+) terminal of the supply, the anode carries a positive charge, and a positive electrode attracts negative ions, so the \(\text{Cl}^{-}\) anions migrate to it and are oxidized to \(\text{Cl}_2\) gas. Because the cathode is connected to the negative (\(-\)) terminal, it carries a negative charge, and a negative electrode attracts positive ions, so the \(\text{Mg}^{2+}\) cations migrate to it and are reduced to magnesium metal. This obeys the universal rules that the cathode attracts cations and the anode attracts anions, with the electrolytic sign convention being anode (+) and cathode (\(-\)). (Choice A) assigns the galvanic-cell signs of anode negative and cathode positive to an electrolytic cell; although the ion-attraction pairing it lists happens to be correct, the signs are backward, since a driven cell has a positive anode and a negative cathode. (Choice C) keeps the correct electrolytic signs but reverses the ion attraction, drawing cations to the positive anode and anions to the negative cathode; because like charges repel, cations are instead drawn to the negative cathode and anions to the positive anode. (Choice D) swaps the half-reaction sites by placing reduction at the anode and oxidation at the cathode; oxidation always occurs at the anode and reduction always occurs at the cathode in every electrochemical cell. Skill 2$ex18$,
    'medium', '4C', $cc18$Electrochemistry (GC)$cc18$, 'general-chemistry', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'reversed_relationship', $a18A$applies galvanic-cell electrode signs (anode negative, cathode positive) to an electrolytic cell$a18A$ FROM q
UNION ALL SELECT id, 'C', 'reversed_relationship', $a18C$reverses ion attraction so cations go to the positive anode and anions to the negative cathode$a18C$ FROM q
