-- Q22 [Cell Diagram Notation · medium · Skill 2 · 4C Electrochemistry (GC) · ans D] (g24)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Electrochemistry', 'Cell Diagram Notation',
    $qt24$In a galvanic cell, a magnesium electrode is paired with a cadmium electrode under standard conditions. The relevant standard reduction potentials are \(E^{\circ}_{\text{Mg}^{2+}/\text{Mg}} = -2.37\ \text{V}\) and \(E^{\circ}_{\text{Cd}^{2+}/\text{Cd}} = -0.40\ \text{V}\). A student writes the spontaneous cell using line notation as \(\text{Cd(s)}\,|\,\text{Cd}^{2+}\,||\,\text{Mg}^{2+}\,|\,\text{Mg(s)}\). The cell as physically constructed does operate spontaneously, but this written diagram contains exactly one error. Which statement correctly identifies the error?$qt24$,
    $op24$[{"label":"A","text":"The electrode phases are reversed; the solid metals belong adjacent to the salt bridge, so the diagram should read \\(\\text{Cd}^{2+}\\,|\\,\\text{Cd(s)}\\,||\\,\\text{Mg(s)}\\,|\\,\\text{Mg}^{2+}\\)."},{"label":"B","text":"The double vertical line is misused; a salt bridge should be shown as a single vertical line, so the diagram should read \\(\\text{Cd(s)}\\,|\\,\\text{Cd}^{2+}\\,|\\,\\text{Mg}^{2+}\\,|\\,\\text{Mg(s)}\\)."},{"label":"C","text":"The diagram is correct as written, because cadmium has the less negative reduction potential and is therefore oxidized at the anode, which is properly placed on the left."},{"label":"D","text":"The half-cells are written in reversed order: by convention the anode is placed on the left, and because magnesium has the more negative reduction potential it is oxidized (the anode), so the diagram should read \\(\\text{Mg(s)}\\,|\\,\\text{Mg}^{2+}\\,||\\,\\text{Cd}^{2+}\\,|\\,\\text{Cd(s)}\\)."}]$op24$::jsonb,
    'D',
    $ex24$This is a General Chemistry question that falls under the content category 'Electrochemistry (GC)'. The answer to this question is D because cell line notation always writes the anode (oxidation) half-cell on the left and the cathode (reduction) half-cell on the right, separated by a double vertical line representing the salt bridge. To assign the electrodes, compare reduction potentials: the species with the more negative standard reduction potential is the one more easily oxidized and therefore serves as the anode. Here \(E^{\circ}_{\text{Mg}^{2+}/\text{Mg}} = -2.37\ \text{V}\) is far more negative than \(E^{\circ}_{\text{Cd}^{2+}/\text{Cd}} = -0.40\ \text{V}\), so magnesium is oxidized (anode) and cadmium is reduced (cathode). This also yields a spontaneous cell: \(E^{\circ}_{\text{cell}} = E^{\circ}_{\text{red,cathode}} - E^{\circ}_{\text{red,anode}} = (-0.40) - (-2.37) = +1.97\ \text{V} > 0\). The student's diagram places Mg (the anode) on the right and Cd (the cathode) on the left, which reverses the conventional order. The single correct fix is to swap the half-cells so the anode is on the left: \(\text{Mg(s)}\,|\,\text{Mg}^{2+}\,||\,\text{Cd}^{2+}\,|\,\text{Cd(s)}\). (Choice A) This describes a nonexistent fault; within each half-cell the solid electrode is written at the outer edge and the ion adjacent to the salt bridge, which the original notation already does, so the electrode-phase ordering is not the source of the error. (Choice B) This reverses the meaning of the line symbols: a single vertical line denotes a phase boundary within one half-cell, while the double vertical line correctly denotes the salt bridge between the two half-cells; the original notation used the double line appropriately, so this is not the error. (Choice C) This inverts the oxidation criterion; the more easily oxidized metal is the one with the more negative reduction potential (Mg at \(-2.37\ \text{V}\)), not the less negative one (Cd at \(-0.40\ \text{V}\)), so cadmium is reduced at the cathode rather than oxidized at the anode. Skill 2$ex24$,
    'medium', '4C', $cc24$Electrochemistry (GC)$cc24$, 'general-chemistry', 2, 110
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'A', 'process_step_confusion', $a24A$invents an electrode-vs-ion placement fault that does not exist$a24A$ FROM q
UNION ALL SELECT id, 'B', 'misconception', $a24B$confuses single vs double vertical line meaning in line notation$a24B$ FROM q
UNION ALL SELECT id, 'C', 'reversed_relationship', $a24C$treats less-negative reduction potential as the more easily oxidized species$a24C$ FROM q;

-- Q23 [Cell Diagram Notation · hard · Skill 2 · 4C Electrochemistry (GC) · ans A] (g25)
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES (
    'chem_phys', 'Electrochemistry', 'Cell Diagram Notation',
    $qt25$A galvanic cell is built by pairing a nickel electrode immersed in \(1\ \text{M}\ \text{Ni}^{2+}(aq)\) with a platinum electrode immersed in a solution that contains both \(\text{Fe}^{3+}(aq)\) and \(\text{Fe}^{2+}(aq)\) at \(1\ \text{M}\); the two half-cells are joined by a salt bridge. The relevant standard reduction potentials are \(E^{\circ}_{\text{Fe}^{3+}/\text{Fe}^{2+}} = +0.77\ \text{V}\) and \(E^{\circ}_{\text{Ni}^{2+}/\text{Ni}} = -0.25\ \text{V}\). Which of the following correctly represents this spontaneous cell using standard cell-diagram (line) notation?$qt25$,
    $op25$[{"label":"A","text":"\\(\\text{Ni}(s)\\,|\\,\\text{Ni}^{2+}\\,||\\,\\text{Fe}^{3+},\\text{Fe}^{2+}\\,|\\,\\text{Pt}(s)\\)"},{"label":"B","text":"\\(\\text{Pt}(s)\\,|\\,\\text{Fe}^{3+},\\text{Fe}^{2+}\\,||\\,\\text{Ni}^{2+}\\,|\\,\\text{Ni}(s)\\)"},{"label":"C","text":"\\(\\text{Ni}(s)\\,|\\,\\text{Ni}^{2+}\\,||\\,\\text{Fe}^{3+},\\text{Fe}^{2+}\\)"},{"label":"D","text":"\\(\\text{Ni}(s)\\,|\\,\\text{Ni}^{2+}\\,|\\,\\text{Fe}^{3+},\\text{Fe}^{2+}\\,|\\,\\text{Pt}(s)\\)"}]$op25$::jsonb,
    'A',
    $ex25$This is a General Chemistry question that falls under the content category 'Electrochemistry (GC)'. The answer to this question is A because the cell must be written with the anode on the left and the cathode on the right, using single vertical lines for phase boundaries and a double vertical line for the salt bridge. Because \(E^{\circ}_{\text{Ni}^{2+}/\text{Ni}} = -0.25\ \text{V}\) is less than \(E^{\circ}_{\text{Fe}^{3+}/\text{Fe}^{2+}} = +0.77\ \text{V}\), the Ni half-cell has the greater tendency to be oxidized, so nickel is the anode (oxidation, left) and the \(\text{Fe}^{3+}/\text{Fe}^{2+}\) couple is the cathode (reduction, right). This orientation gives \(E^{\circ}_{\text{cell}} = E^{\circ}_{\text{red,cathode}} - E^{\circ}_{\text{red,anode}} = (+0.77\ \text{V}) - (-0.25\ \text{V}) = +1.02\ \text{V}\), a positive value confirming a spontaneous galvanic cell. The \(\text{Fe}^{3+}/\text{Fe}^{2+}\) couple is an ion/ion pair with no conducting solid phase of its own, so an inert \(\text{Pt}(s)\) electrode must be written as the right-hand terminal to carry the current. Option A satisfies all of these requirements: \(\text{Ni}(s)\,|\,\text{Ni}^{2+}\,||\,\text{Fe}^{3+},\text{Fe}^{2+}\,|\,\text{Pt}(s)\). (Choice B) This diagram reverses the half-cells, placing the \(\text{Fe}^{3+}/\text{Fe}^{2+}\) couple on the left as the anode and Ni on the right as the cathode; that arrangement describes the nonspontaneous direction and would yield \(E^{\circ}_{\text{cell}} = -1.02\ \text{V}\), so it does not represent the spontaneous cell as required. (Choice C) This diagram omits the inert platinum electrode after the \(\text{Fe}^{3+}/\text{Fe}^{2+}\) couple; because that couple contains no solid metal phase, the cathode half-cell has no defined terminal to conduct electrons and the notation is incomplete. (Choice D) This diagram uses a single vertical line where the salt bridge belongs; a single line denotes a phase boundary within one half-cell, whereas the junction between the two separate half-cells must be marked with a double vertical line. Skill 2$ex25$,
    'hard', '4C', $cc25$Electrochemistry (GC)$cc25$, 'general-chemistry', 2, 160
  ) RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
SELECT id, 'B', 'reversed_relationship', $a25B$swaps anode and cathode, writing the nonspontaneous reverse cell with the inert-electrode couple on the left$a25B$ FROM q
UNION ALL SELECT id, 'C', 'process_step_confusion', $a25C$omits the required inert Pt electrode terminal for the ion/ion couple, leaving the cathode half-cell without a conductor$a25C$ FROM q
UNION ALL SELECT id, 'D', 'misconception', $a25D$uses a single vertical line for the salt bridge instead of the double line, confusing the phase-boundary symbol with the salt-bridge symbol$a25D$ FROM q;

